using System;
using System.IO;
using System.Text;
using System.Linq;
using System.Net;
using System.Net.Sockets;
using System.Threading;
using System.Collections.Generic;
namespace FocusGrowth {
public sealed class Request {public string Method,Path;public Dictionary<string,string> Headers=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);public string Body;}
public sealed class Bridge : IDisposable {
 public const int Port=18417;public const string Local="http://127.0.0.1:18417";public const string Pages="https://tang0709.github.io";
 readonly TcpListener listener=new TcpListener(IPAddress.Loopback,Port);readonly Engine engine;readonly Pairing pair;readonly string web;readonly Func<string,bool> approve;volatile bool stopped;int active;
 public Bridge(Engine e,Pairing p,string webFolder,Func<string,bool> approval){engine=e;pair=p;web=webFolder;approve=approval;}
 public void Start(){listener.Start(16);ThreadPool.QueueUserWorkItem(_=>{while(!stopped)try{var c=listener.AcceptTcpClient();if(Interlocked.Increment(ref active)>8){Interlocked.Decrement(ref active);c.Close();continue;}ThreadPool.QueueUserWorkItem(x=>Handle(c));}catch{if(!stopped)Thread.Sleep(100);}});}
 public static string Origin(Request r){string origin; if(r.Headers.TryGetValue("Origin",out origin))return origin;string site;if(r.Method=="GET"&&r.Headers.TryGetValue("Sec-Fetch-Site",out site)&&site=="same-origin")return Local;return null;}
 public static void Gate(Request r){string host;Schema.Require(r.Headers.TryGetValue("Host",out host)&&host=="127.0.0.1:18417","host_rejected");Schema.Require(r.Method=="GET"||r.Method=="POST"||r.Method=="OPTIONS","method_rejected");if(r.Path=="/health"&&r.Method=="GET")return;if((r.Path=="/"||r.Path=="/sync.js"||r.Path=="/favicon.ico")&&r.Method=="GET")return;Schema.Require(Origin(r)==Local||Origin(r)==Pages,"origin_rejected");}
 static Request Parse(NetworkStream stream){var bytes=new List<byte>();int n;while((n=stream.ReadByte())>=0){bytes.Add((byte)n);if(bytes.Count>16384)throw new Fault("headers_too_large");int c=bytes.Count;if(c>=4&&bytes[c-4]==13&&bytes[c-3]==10&&bytes[c-2]==13&&bytes[c-1]==10)break;}Schema.Require(bytes.Count>0,"invalid_http");var lines=Encoding.ASCII.GetString(bytes.ToArray()).Split(new[]{"\r\n"},StringSplitOptions.None);var first=lines[0].Split(' ');Schema.Require(first.Length==3&&first[2]=="HTTP/1.1"&&first[1].StartsWith("/")&&!first[1].StartsWith("//"),"invalid_http");var r=new Request{Method=first[0],Path=first[1].Split('?')[0]};foreach(var line in lines.Skip(1)){if(line=="")break;int colon=line.IndexOf(':');Schema.Require(colon>0,"invalid_headers");string k=line.Substring(0,colon),v=line.Substring(colon+1).Trim();Schema.Require(!r.Headers.ContainsKey(k)&&!k.Any(Char.IsWhiteSpace),"duplicate_or_invalid_header");r.Headers[k]=v;}Schema.Require(!r.Headers.ContainsKey("Transfer-Encoding"),"transfer_encoding_rejected");int length=0;string raw;if(r.Headers.TryGetValue("Content-Length",out raw))Schema.Require(Int32.TryParse(raw,out length)&&length>=0&&length<=600000,"body_too_large");if(r.Method=="POST"){string type;Schema.Require(r.Headers.TryGetValue("Content-Type",out type)&&type.Split(';')[0].Trim()=="application/json","json_required");Schema.Require(length>0,"body_required");}byte[] body=new byte[length];int read=0;while(read<length){int k=stream.Read(body,read,length-read);Schema.Require(k>0,"truncated_body");read+=k;}try{r.Body=new UTF8Encoding(false,true).GetString(body);}catch{throw new Fault("invalid_utf8");}return r;}
 static void Respond(NetworkStream s,int code,object data,string origin,string type){byte[] b=data is byte[]?(byte[])data:Encoding.UTF8.GetBytes(J.Dump(data));var headers="HTTP/1.1 "+code+" Result\r\nConnection: close\r\nContent-Length: "+b.Length+"\r\nContent-Type: "+type+"\r\nCache-Control: no-store\r\nX-Content-Type-Options: nosniff\r\nReferrer-Policy: no-referrer\r\n";if(origin==Local||origin==Pages)headers+="Access-Control-Allow-Origin: "+origin+"\r\nVary: Origin\r\nAccess-Control-Allow-Methods: GET, POST, OPTIONS\r\nAccess-Control-Allow-Headers: Authorization, Content-Type, X-FG-Client\r\nAccess-Control-Allow-Private-Network: true\r\n";byte[] h=Encoding.ASCII.GetBytes(headers+"\r\n");s.Write(h,0,h.Length);s.Write(b,0,b.Length);}
 void Handle(TcpClient client){Request r=null;try{using(client){client.ReceiveTimeout=5000;client.SendTimeout=5000;using(var stream=client.GetStream()){try{r=Parse(stream);Gate(r);string origin=Origin(r);
   if(r.Method=="OPTIONS"){Schema.Require(new[]{"/v1/pair","/v1/state","/v1/changes","/v1/sync","/v1/resolve"}.Contains(r.Path),"route_rejected");string method;Schema.Require(r.Headers.TryGetValue("Access-Control-Request-Method",out method)&&(method=="GET"||method=="POST"),"preflight_rejected");Respond(stream,204,new byte[0],origin,"application/json");return;}
   if(r.Path=="/health"&&r.Method=="GET"){Respond(stream,200,new{version="0.3-test",mode="synthetic",productionLocked=true},null,"application/json");return;}
   if((r.Path=="/"||r.Path=="/sync.js")&&r.Method=="GET"){Respond(stream,200,File.ReadAllBytes(Path.Combine(web,r.Path=="/"?"index.html":"sync.js")),null,r.Path=="/"?"text/html; charset=utf-8":"text/javascript; charset=utf-8");return;}
   if(r.Path=="/v1/pair"&&r.Method=="POST"){var d=J.Obj(J.Parse(r.Body));Schema.Require(d.Count==1&&d.ContainsKey("code"),"invalid_pair_body");string token=pair.Pair(J.Str(d["code"]),origin,approve);Respond(stream,200,new{session=token,expiresIn=900,mode="synthetic",productionLocked=true},origin,"application/json");return;}
   string authorization,csrf;Schema.Require(r.Headers.TryGetValue("X-FG-Client",out csrf)&&csrf=="1"&&r.Headers.TryGetValue("Authorization",out authorization)&&authorization.StartsWith("Bearer ")&&pair.Auth(authorization.Substring(7),origin),"unauthorized");
   if(r.Path=="/v1/state"&&r.Method=="GET"){Respond(stream,200,engine.View(),origin,"application/json");return;}
   if(r.Path=="/v1/changes"&&r.Method=="POST"){engine.Queue(J.Obj(J.Parse(r.Body)));engine.Sync(false);Respond(stream,202,engine.View(),origin,"application/json");return;}
   if(r.Path=="/v1/resolve"&&r.Method=="POST"){engine.Resolve(J.Obj(J.Parse(r.Body)));engine.Sync(false);Respond(stream,202,engine.View(),origin,"application/json");return;}
   if(r.Path=="/v1/sync"&&r.Method=="POST"){Schema.Require(J.Obj(J.Parse(r.Body)).Count==0,"invalid_sync_body");engine.Sync(true);Respond(stream,200,engine.View(),origin,"application/json");return;}
   throw new Fault("route_rejected");
  }catch(Fault ex){Respond(stream,ex.Code=="unauthorized"?401:ex.Code.Contains("conflict")?409:400,new{error=ex.Code},r==null?null:Origin(r),"application/json");}catch{Respond(stream,500,new{error="request_failed"},null,"application/json");}}}}catch{}finally{Interlocked.Decrement(ref active);}}
 public void Dispose(){stopped=true;listener.Stop();}
}
}
